27: /// The colour a ray sees: its scattered path attenuated by each material, the sky gradient when it
28: /// misses.
29: fn ray_colour(ray: &Ray, world: &dyn Hittable, rng: &mut Rng) -> Colour {
30:     let mut ray = *ray;
31:     let mut colour = Vec3::new(1.0, 1.0, 1.0);
32:     for _ in 0..MAX_BOUNCES {
33:         if let Some(hit) = world.hit(&ray, 0.001, f64::INFINITY) {
34:             match hit.material.scatter(&ray, &hit, rng) {
35:                 Some((attenuation, scattered)) => {
36:                     colour = colour * attenuation;
37:                     ray = scattered;
38:                 }
39:                 None => return Vec3::new(0.0, 0.0, 0.0),
40:             }
41:         } else {
42:             return colour * sky_colour(&ray);
43:         }
44:     }
45:     Vec3::new(0.0, 0.0, 0.0)
46: }
47: 
48: /// The sky gradient a ray sees when it misses the scene: white at the horizon, blue above.
49: fn sky_colour(ray: &Ray) -> Colour {
50:     let t = 0.5 * (ray.direction.unit().y + 1.0);
51:     Vec3::new(1.0, 1.0, 1.0) * (1.0 - t) + Vec3::new(0.5, 0.7, 1.0) * t
52: }
